# Use a more precise symbol lookup with readelf
python3 -c "
import subprocess, re

# Get all dynamic symbols with their sizes
out = subprocess.check_output(['readelf', '--dyn-syms', '-W', 'symbols/libmonosgen-2.0.so'], text=True)
syms = []
for line in out.splitlines():
    parts = line.split()
    if len(parts) >= 8 and parts[3] == 'FUNC':
        addr = int(parts[1], 16)
        size = int(parts[2])
        name = parts[7].split('@')[0]
        if addr > 0:
            syms.append((addr, size, name))
syms.sort()

# Lookup addresses
targets = {
    '#01': 0x222098,
    '#02': 0x222234,
    '#03': 0x19bac0,
    '#06': 0x19bc14,
}

for frame, pc in targets.items():
    found = None
    for addr, size, name in syms:
        if addr <= pc < addr + size:
            found = (name, pc - addr)
            break
    if not found:
        # fallback: nearest symbol before
        for i, (addr, size, name) in enumerate(syms):
            if addr > pc:
                prev = syms[i-1]
                found = (prev[2], pc - prev[0])
                break
    if found:
        print(f'  {frame} pc {hex(pc)} -> {found[0]}+{hex(found[1])}')
    else:
        print(f'  {frame} pc {hex(pc)} -> ???')
"

